    /**
     * 查询所有实例ID
     *
     * @return 实例ID列表
     */
    public static List<Integer> queryAllInstanceIds() {
        try {
            Map<String, String> respHeaderMap = new RestCaller.Builder(POLICY_URL, RestMethod.POST)
                .header(BACKEND_LIST_POLICY_HEADER, INSTANCE_ONLY_POLICY)
                .build()
                .call()
                .getRespHeaderMap();
            String backendList = getBackendList(respHeaderMap);
            if (!backendList.startsWith(ALL_INSTANCES_PREFIX)) {
                LOGGER.info("BackendList not start with all=");
                return new ArrayList<>();
            }
            String instancesStr = backendList.substring(ALL_INSTANCES_PREFIX.length());
            return Arrays.stream(instancesStr.split(INSTANCE_ID_SEPARATOR))
                .map(String::trim)
                .filter(instance -> !instance.isEmpty())
                .flatMap(instance -> parseInstanceId(instance).stream())
                .collect(Collectors.toList());
        } catch (ServiceException e) {
            LOGGER.warn("Query all instance ids failed with ServiceException, message: " + e.getMessage());
