        if (parts.length < 2) {
            LOGGER.info("Invalid instance name format, cannot parse as id: " + instanceName);
            return Optional.empty();
        }
        String lastPart = parts[parts.length - 1];
        if (StringUtil.isEmpty(lastPart)) {
            LOGGER.info("Invalid instance name format, last part is empty: " + instanceName);
            return Optional.empty();
        }
        try {
            int id = Integer.parseInt(lastPart);
